import {LOCAL_SERVICE,HOSTED_SERVICE} from './runtime.js';
import {PRIVATE_LEARNING_URL} from './connection-info.js';
import * as C from './core.js';

export function buildLearningSnapshot(state){
 const date=C.today(),d=state.days[date];
 return {type:'YAN-shared-learning',version:1,date,summary:{learnedWords:Object.keys(state.cards).length,dueWords:C.dueIds(state).length,streak:C.streak(state),todayNew:d?.wordDone.length||0,todayReview:d?.reviewDone.length||0,todayGrammar:d?.grammarDone.length||0,targetDate:state.settings.targetDate,targetBand:state.settings.targetBand},world:(state.world?.collection||[]).slice(0,100).map(w=>({word:w.word,meaning:w.meaning,example:w.example,translation:w.translation,expression:w.expression,expressionTranslation:w.expressionTranslation,scene:w.scene,foundAt:w.foundAt,...(w.origin==='local'?{origin:'local'}:{}),due:state.cards[w.id]?.due||null})),mistakes:state.mistakes.filter(x=>!x.resolved).slice(-100).map(x=>Object.fromEntries(['category','prompt','answer','userAnswer','note'].map(k=>[k,String(x[k]).slice(0,1000)]))),records:state.records.slice(-20).map(x=>({date:x.date,skill:x.skill,title:x.title.slice(0,200),correct:x.correct,total:x.total,feedback:x.feedback.slice(0,1000),nextAction:x.nextAction.slice(0,1000)}))};
}
export function createConnections({esc,button,refresh,toast,getState,onModelChange}){
 let auth=null,models=[],cloud=null,error='',busy=false,preview=null,shareAllowed=false;
 async function api(path,body,method){
  const res=await fetch('./api/'+path,{method:method||(body?'POST':'GET'),headers:{'X-Yan-Client':'1',...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',redirect:'error'});
  const data=await res.json().catch(()=>{throw new Error('当前地址未提供这个连接服务。');});if(!res.ok)throw new Error(data.error||'操作未完成。');return data;
 }
 function page(){return `<details class="panel glass connections-panel" ${auth||cloud||models.length||preview||busy||error?'open':''}><summary>连接我的 ChatGPT · 登录与 MCP</summary><p class="body-copy">让熟悉的 ChatGPT 参与学习。账号授权与学习数据分享分别由你决定，不会自动带入原聊天和其他应用记忆。</p><div class="connection-grid"><section><h2>在网页里使用 ChatGPT</h2>${LOCAL_SERVICE?`<p class="caption">本机版按官方开源应用流程授权；需要这个 ChatGPT 账号开放额度使用权限。手机经同一电脑配对可使用，电脑须保持运行。</p><p>${auth?.connected?'已授权账号：'+esc(auth.account):'尚未验证 ChatGPT 授权'}</p><p class="caption">${esc(auth?.message||'先读取连接状态，或开始官方登录。')}</p><div class="actions">${button('读取 ChatGPT 连接状态','connect-auth-status',busy?'disabled':'','btn secondary')}</div><form id="chatgpt-signin-form"><div class="field"><label for="chatgpt-profile">选择 ChatGPT 账号注册</label><select id="chatgpt-profile" name="profileId"><option value="">添加其他账号 / 首次登录</option>${(auth?.profiles||[]).map(x=>`<option value="${esc(x.id)}" ${auth.active===x.id?'selected':''}>${esc(x.label)}${x.authorized?' · 已授权':''}</option>`).join('')}</select></div><button class="btn secondary" type="submit" ${busy?'disabled':''}>Continue with ChatGPT</button></form>${auth?.connected?`<div class="actions">${button('读取账号可用模型','connect-models',busy?'disabled':'','btn secondary')}${button('退出 ChatGPT 连接','connect-signout',busy?'disabled':'','btn ghost')}</div>`:''}${models.length?`<form id="chatgpt-model-form"><div class="field"><label for="chatgpt-model">此账号可用的模型</label><select id="chatgpt-model" name="model">${models.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div><button class="btn" type="submit" ${busy?'disabled':''}>用这个 ChatGPT 模型陪我学习</button></form>`:''}`:`<p class="notice warm">手机独立网页的 ChatGPT 额度登录尚未开通。官方开源授权目前要求本机回调；托管网页登录需另行获得官方接入资格。</p><p class="caption">${HOSTED_SERVICE?'这个私有站点的 ChatGPT 登录用于确认你的身份和保护学习快照，不代表已获得模型调用权限。':'当前可继续使用上方已有 API，或使用电脑本机版的官方 ChatGPT 授权。'}本项目不会收取你的 ChatGPT 密码、Cookie 或会话令牌。</p><a href="https://developers.openai.com/siwc/token-sharing-open-source" target="_blank" rel="noopener noreferrer">查看官方接入说明 ↗</a>`}</section><section><h2>让 ChatGPT 使用学习工具</h2><p class="body-copy">通过 MCP 查询词库与原创材料；读取进度和错题时，只提供你主动分享的副本。工具不能修改学习记录，也不能读取聊天、照片或 API 密钥。</p>${HOSTED_SERVICE?`<div class="actions">${button('查看私有连接状态','connect-cloud-status',busy?'disabled':'','btn secondary')}${button('预览要分享的学习数据','connect-preview',busy?'disabled':'','btn secondary')}</div>${cloud?`<p class="caption">登录身份：${esc(cloud.account)}<br>分享副本：${cloud.sharedDate?esc(cloud.sharedDate):'尚未分享'}</p><div class="field"><label for="mcp-url">MCP 地址（在 ChatGPT 中添加连接）</label><input id="mcp-url" readonly value="${esc(cloud.mcpUrl)}"></div>`:''}${preview?`<div class="notice"><p>将分享截至 ${esc(preview.date)} 的学习概况、${preview.mistakes.length} 条未解决错题和 ${preview.records.length} 条练习记录及 ${preview.world?.length||0} 个探索收藏词。只更新副本，不自动同步。</p><details><summary>查看本次完整分享内容</summary><pre class="connection-preview">${esc(JSON.stringify(preview,null,2))}</pre></details><label class="check-label"><input id="connect-share-consent" type="checkbox" ${shareAllowed?'checked':''}>允许将以上内容保存到我的私有站点，并供已授权的 ChatGPT MCP 读取</label><div class="actions">${button('确认分享给我的 ChatGPT','connect-share',busy?'disabled':'')}${button('取消这次分享','connect-preview-cancel','','btn ghost')}</div></div>`:''}${cloud?.sharedDate?button('撤回已分享的副本','connect-unshare',busy?'disabled':'','btn ghost'):''}<p class="caption">私有站点与公开网页的记录相互独立。首次使用时，可在原网页导出学习备份，再到本站「数据与设置」导入；导入本身不触发分享。</p>`:PRIVATE_LEARNING_URL?`<a class="btn secondary" href="${esc(PRIVATE_LEARNING_URL)}#ai" target="_blank" rel="noopener noreferrer">打开我的私有 ChatGPT 学习连接 ↗</a><p class="caption">在私有站点登录后，导入学习备份、预览并确认分享，再在 ChatGPT 安装对应的私人插件。打开这个链接不会自动上传此网页的数据。</p>`:'<p class="caption">私有 MCP 服务尚未发布，暂时没有可连接的网址；这里不会把当前网页冒充 MCP 服务。</p>'}</section></div>${busy?'<p role="status">正在处理连接操作…</p>':''}${error?`<p class="notice warm" role="alert">${esc(error)}</p>`:''}</details>`;}
 async function run(fn){if(busy)return;busy=true;error='';refresh();try{await fn();}catch(e){error=e.message||'连接未完成，请重试。';}finally{busy=false;refresh();}}
 function act(action){
  if(!action.startsWith('connect-'))return false;
  if(action==='connect-auth-status'&&LOCAL_SERVICE)run(async()=>{auth=await api('chatgpt/status');});
  if(action==='connect-models'&&LOCAL_SERVICE)run(async()=>{models=(await api('chatgpt/models')).models;});
  if(action==='connect-signout'&&LOCAL_SERVICE)run(async()=>{await api('chatgpt/signout',{});models=[];auth=await api('chatgpt/status');await onModelChange();});
  if(action==='connect-cloud-status'&&HOSTED_SERVICE)run(async()=>{cloud=await api('connections/status');});
  if(action==='connect-preview'&&HOSTED_SERVICE){preview=buildLearningSnapshot(getState());shareAllowed=false;refresh();}
  if(action==='connect-preview-cancel'){preview=null;shareAllowed=false;refresh();}
  if(action==='connect-share'&&HOSTED_SERVICE)run(async()=>{if(!preview||!shareAllowed)throw new Error('请先预览内容并勾选本次分享许可。');await api('connections/snapshot',preview);preview=null;shareAllowed=false;cloud=await api('connections/status');toast('已分享一份学习副本；之后的变化不会自动同步。');});
  if(action==='connect-unshare'&&HOSTED_SERVICE)run(async()=>{await api('connections/snapshot',undefined,'DELETE');cloud=await api('connections/status');toast('已撤回分享副本，本机学习记录仍保留。');});
  return true;
 }
 async function submit(form,values){
  if(form.id==='chatgpt-signin-form'&&LOCAL_SERVICE){await run(async()=>{const data=await api('chatgpt/signin',{profileId:values.profileId||''});const target=new URL(data.authorizationUrl);if(target.origin!=='https://auth.openai.com')throw new Error('登录地址不匹配，已停止跳转。');window.location.assign(target.href);});return true;}
  if(form.id==='chatgpt-model-form'&&LOCAL_SERVICE){await run(async()=>{if(!models.some(x=>x.id===values.model))throw new Error('请选择已读取到的账号模型。');await api('ai/config',{provider:'chatgpt',model:values.model});await onModelChange();toast('已选择 ChatGPT。发送文字前仍需要本次许可。');});return true;}
  return false;
 }
 const input=e=>{if(e.target.id==='connect-share-consent')shareAllowed=e.target.checked;};
 return {page,act,submit,input};
}
